import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the CUDA kernel for matrix multiplication with transposed B and loop unrolling
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];  // Transposed storage for B

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    for (int tile = 0; tile < (N + TILE_SIZE - 1) / TILE_SIZE; tile++) {
        // Load tile from A into shared memory
        int a_col = tile * TILE_SIZE + threadIdx.x;
        if (row < N && a_col < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Load tile from B into shared memory (transposed)
        int b_row = tile * TILE_SIZE + threadIdx.y;
        int b_col = col;
        if (b_row < N && b_col < N) {
            // Store in transposed order (threadIdx.x, threadIdx.y) instead of (threadIdx.y, threadIdx.x)
            Bs[threadIdx.x][threadIdx.y] = B[b_row * N + b_col];
        } else {
            Bs[threadIdx.x][threadIdx.y] = 0.0f;
        }

        __syncthreads();

        // Compute partial sum with loop unrolling
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
            float a_val[UNROLL_FACTOR];
            float b_val[UNROLL_FACTOR];

            // Prefetch values into registers
            for (int i = 0; i < UNROLL_FACTOR; i++) {
                if (k + i < TILE_SIZE) {
                    a_val[i] = As[threadIdx.y][k + i];
                    b_val[i] = Bs[threadIdx.x][k + i];
                } else {
                    a_val[i] = 0.0f;
                    b_val[i] = 0.0f;
                }
            }

            // Accumulate with unrolled loop
            for (int i = 0; i < UNROLL_FACTOR; i++) {
                sum += a_val[i] * b_val[i];
            }
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

